-- PostgreSQL/Supabase reference schema.
-- The FastAPI application creates the same tables automatically on startup.
-- For production, replace create_all with a migration tool such as Alembic.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'ATTENDEE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS events (id SERIAL PRIMARY KEY, organizer_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_name VARCHAR(180) NOT NULL, description TEXT NOT NULL, event_type VARCHAR(80) NOT NULL, event_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, venue VARCHAR(200) NOT NULL, online_link VARCHAR(500), maximum_capacity INTEGER NOT NULL CHECK(maximum_capacity > 0), registration_deadline TIMESTAMPTZ NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rsvps (id SERIAL PRIMARY KEY, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status VARCHAR(20) NOT NULL, responded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_rsvp_event_user UNIQUE(event_id,user_id));
CREATE TABLE IF NOT EXISTS waitlist (id SERIAL PRIMARY KEY, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), status VARCHAR(20) NOT NULL DEFAULT 'WAITING', CONSTRAINT uq_waitlist_event_user UNIQUE(event_id,user_id));
CREATE TABLE IF NOT EXISTS announcements (id SERIAL PRIMARY KEY, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id INTEGER REFERENCES events(id) ON DELETE SET NULL, type VARCHAR(50) NOT NULL, message TEXT NOT NULL, read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, action VARCHAR(120) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
